/* ElectroStore demo UI — client-side behaviours only. No real authentication or payments. */
(() => {
'use strict';
const $ = (selector, root=document) => root.querySelector(selector);
const $$ = (selector, root=document) => Array.from(root.querySelectorAll(selector));
const storage = {
  read(key, fallback) { try { const raw=localStorage.getItem('electro_'+key); return raw ? JSON.parse(raw) : fallback; } catch { return fallback; } },
  write(key, value) { try { localStorage.setItem('electro_'+key, JSON.stringify(value)); } catch (e) { console.warn('Local demo storage unavailable', e); } }
};
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lkrFormatter = new Intl.NumberFormat('en-LK', {style:'currency',currency:'LKR'});
const money = amount => lkrFormatter.format(Number(amount || 0)).replace(/LKR\s?/, 'Rs. ');
const clean = value => String(value ?? '').trim();
const imagePath = name => {
  const value = String(name || '');
  if (/^https:\/\/[^\s"']+$/i.test(value)) return value;
  if (/^assets\/images\/products\/[\w.-]+\.(?:webp|jpe?g|png)$/i.test(value)) return value;
  if (/^images\/products\/[\w.-]+\.(?:webp|jpe?g|png)$/i.test(value)) return `assets/${value}`;
  return 'assets/img/' + (['laptop.svg','phone.svg','headphones.svg','camera.svg','tablet.svg','watch.svg'].includes(value) ? value : 'laptop.svg');
};
const categories = ['Laptops','Mobile Phones','Headphones','Cameras','Accessories'];
const icons = {
  cart:'<path d="m3 3 2 2h2l2 11h10l2-9H7"/><circle cx="10" cy="21" r="1"/><circle cx="19" cy="21" r="1"/>',
  user:'<path d="M20 21a8 8 0 0 0-16 0"/><circle cx="12" cy="8" r="4"/>',
  search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',
  bag:'<path d="M4 8h16l-1 13H5L4 8Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/>',
  heart:'<path d="M20.8 5.7c-2-2.1-5.2-2.1-7.2 0l-1.6 1.6-1.6-1.6a5.1 5.1 0 0 0-7.2 7.2L12 22l8.8-9.1a5.1 5.1 0 0 0 0-7.2Z"/>',
  laptop:'<rect x="4" y="4" width="16" height="13" rx="2"/><path d="m2 20 2-3h16l2 3H2Z"/>',
  phone:'<rect x="7" y="2" width="10" height="20" rx="2"/><path d="M11 19h2"/>',
  headphones:'<path d="M3 14v-3a9 9 0 0 1 18 0v3"/><rect x="2" y="13" width="5" height="8" rx="2"/><rect x="17" y="13" width="5" height="8" rx="2"/>',
  camera:'<path d="M3 7h4l2-3h6l2 3h4v13H3V7Z"/><circle cx="12" cy="13" r="4"/>',
  accessory:'<rect x="7" y="2" width="10" height="20" rx="4"/><path d="M7 7H3m18 0h-4"/>',
  shield:'<path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11Z"/><path d="m9 12 2 2 4-4"/>',
  truck:'<path d="M2 5h13v11H2zM15 9h4l3 4v3h-7"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',
  arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
  minus:'<path d="M5 12h14"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  trash:'<path d="M3 6h18m-2 0-1 15H6L5 6m4-3h6l1 3M10 10v8m4-8v8"/>',
  menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
  close:'<path d="M5 5l14 14M19 5 5 19"/>',
  chart:'<path d="M3 21V3M3 21h18M7 16l4-5 4 3 5-8"/>',
  box:'<path d="m12 2 9 5-9 5-9-5 9-5Z M3 7v10l9 5 9-5V7 M12 12v10"/>',
  orders:'<path d="M7 3h10l3 3v15H4V6l3-3Z M8 10h8M8 14h8M8 18h5"/>',
  settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M4.9 4.9 7 7m10 10 2.1 2.1M19.1 4.9 17 7M7 17l-2.1 2.1"/>',
  logout:'<path d="M9 4H4v16h5m3-12 4 4-4 4m-5-4h9"/>',
  check:'<path d="m5 12 5 5L20 7"/>',
  star:'<path d="m12 2 3 6 7 .9-5 5 1.2 7-6.2-3.2L5.8 21 7 14l-5-5 7-.9L12 2Z"/>',
  mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 6 10 8L22 6"/>',
  lock:'<rect x="4" y="10" width="16" height="12" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
  filter:'<path d="M3 5h18M6 12h12M9 19h6"/>'
};
const icon = (name, size=20) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${icons[name] || icons.box}</svg>`;
const productList = () => (window.ELECTRO_REMOTE_PRODUCTS || []).map(p=>({...p,id:Number(p.id),price:Number(p.deal_id?p.deal_price:p.price),originalPrice:Number(p.original_price||p.price),stock:Number(p.stock),oldPrice:Number(p.original_price||p.oldPrice||p.price),rating:Number(p.rating||4.5),image:p.image||'laptop.svg'}));
const getProduct = id => productList().find(p=>p.id === Number(id));
const cart = () => window.ELECTRO_REMOTE_CART || [];
const countCart = () => cart().reduce((n,p)=>n + p.qty,0);
const cartRows = () => cart().map(i=>({...i,product:getProduct(i.id)})).filter(i=>i.product);
const subtotal = () => cartRows().reduce((sum,row)=>sum + row.qty*row.product.price,0);
const wishlist = () => storage.read('wishlist',[]);
const user = () => window.ELECTRO_REMOTE_USER || null;
const orders = () => (window.ELECTRO_REMOTE_ADMIN_ORDERS || window.ELECTRO_REMOTE_ORDERS || []).map(normalizeOrder);
const normalizeOrder = o => ({...o,id:o.id,date:o.created_at||o.date,total:Number(o.total||0),status:o.status,customer:{name:o.customer_name||o.customer?.name||'',email:o.customer_email||o.customer?.email||''},items:o.items||[]});
const uid = () => 'ORD-' + Date.now().toString().slice(-8);
const params = new URLSearchParams(location.search);
const page = document.body.dataset.page;
let selectedFilter = {categories:[],prices:[],sort:'popular',query:params.get('q')||''};
function toast(message, type='ok') { const e=$('#toast');if(!e)return;e.textContent=message;e.className=`visible ${type}`;window.clearTimeout(toast._t);toast._t=window.setTimeout(()=>e.className='',3000); }
async function refreshRemoteCart(){ if(!user()){window.ELECTRO_REMOTE_CART=[];return;} const result=await ElectroAPI.get('cart');window.ELECTRO_REMOTE_CART=result.data.map(i=>({id:Number(i.id),qty:Number(i.qty)})); }
function saveCart(items) { window.ELECTRO_REMOTE_CART=items; $$('.cart-count').forEach(e=>e.textContent=countCart()); }
async function addCart(id, qty=1) { const p=getProduct(id);if(!p){toast('Product not available','err');return;}if(!user()){toast('Please sign in before adding items','err');location.href='login.html';return;}try{await ElectroAPI.post('cart_add',{product_id:id,quantity:qty});await refreshRemoteCart();saveCart(window.ELECTRO_REMOTE_CART);toast(p.name+' added to cart');}catch(e){toast(e.message,'err');} }
function shell(content, opts={}) { const isAdmin=!!opts.admin; return isAdmin ? adminShell(content) : `${header()}<main id="main">${content}</main>${footer()}`; }
function header(){ const current=page;const adminLink=user()?.role==='admin'?'<a class="btn btn-outline btn-small admin-dashboard-link" href="admin.html">Admin Dashboard</a>':'';return `<header class="site-header"><div class="header-inner"><a class="brand" href="index.html">Electro<span>Store</span></a><nav class="header-nav" aria-label="Main"><a class="${current==='home'?'active':''}" href="index.html">Home</a><a class="${current==='products'||current==='product'?'active':''}" href="products.html">Products</a><a href="products.html?sort=deals">Deals</a><a href="mailto:support@example.com?subject=ElectroStore%20Demo">Contact</a></nav><form class="header-search" id="header-search" action="products.html"><label class="sr-only" for="global-search">Search products</label><input id="global-search" name="q" placeholder="Search products..." value="${esc(params.get('q')||'')}">${`<button aria-label="Search">${icon('search',19)}</button>`}</form><div class="header-actions">${adminLink}<a class="header-cart" href="cart.html">${icon('cart',18)} <span>Cart (<span class="cart-count">${countCart()}</span>)</span></a><a class="btn btn-primary btn-small" href="${user()?'profile.html':'login.html'}">${user()?'My Profile':'Sign In'}</a><button class="mobile-menu-btn icon-button" data-action="toggle-menu" aria-label="Toggle menu">${icon('menu',22)}</button></div></div></header>`;}
function footer(){return `<footer class="site-footer"><div class="container footer-inner"><span>© 2026 ElectroStore. All rights reserved.</span><span><a href="mailto:support@example.com">Privacy</a> · <a href="mailto:support@example.com">Terms</a> · <a href="mailto:support@example.com">Support</a> · <a href="admin-login.html">Admin</a></span></div></footer>`;}
const storefrontHeader = header;
header = () => storefrontHeader().replace('products.html?sort=deals','deals.html');
const headerWithSuggestions = header;
header = () => headerWithSuggestions().replace('</form><div class="header-actions">','</form><div class="search-suggestions" id="search-suggestions" role="listbox" hidden></div><div class="header-actions">');
const categoriesHome=[['Laptops','laptop'],['Mobile Phones','phone'],['Headphones','headphones'],['Cameras','camera']];
function card(p,opts={}) {return `<article class="product-card"><a href="product.html?id=${p.id}" class="product-art"><img src="${imagePath(p.image)}" alt="${esc(p.name)} illustration" loading="lazy"></a><div class="product-card-body"><a class="product-title" href="product.html?id=${p.id}">${esc(p.name)}</a>${opts.meta?`<span class="product-category">${esc(p.category)}</span>`:''}<div class="product-card-bottom"><span class="product-price">${money(p.price)}</span><button class="btn btn-primary btn-product" data-action="add-cart" data-id="${p.id}">Add to Cart</button></div></div></article>`;}
const baseProductCard=card;
card=(p,opts={})=>baseProductCard(p,opts).replace(opts.meta?`<span class="product-category">${esc(p.category)}</span>`:'',opts.meta?`<span class="product-category">${esc(p.brand||p.category)}</span>`:'');
function renderHome(){const featured=productList().filter(p=>[1,2,3,4].includes(p.id));return shell(`<section class="hero"><div class="container hero-inner"><div class="hero-copy"><h1>Latest Tech.<br>Better Life.</h1><p>Shop the newest laptops, phones, and accessories at unbeatable prices — all in one secure store.</p><a class="btn btn-primary" href="products.html">Shop Now</a></div><div class="hero-art"><img src="assets/img/hero.svg" alt="Illustration of a laptop, phone and headphones"></div></div></section><section class="container section categories-section"><h2>Shop by Category</h2><div class="category-grid">${categoriesHome.map(([cat,ic])=>`<a class="category-tile" href="products.html?category=${encodeURIComponent(cat)}"><div class="category-icon">${icon(ic,23)}</div><span>${esc(cat)}</span></a>`).join('')}</div></section><section class="container section popular-section"><div class="section-heading"><h2>Popular Products</h2><a class="text-link" href="products.html">View all ${icon('arrow',16)}</a></div><div class="products-grid four">${featured.map(p=>card(p)).join('')}</div></section>`);}
function priceMatch(p,r){if(r==='under100')return p.price<30000;if(r==='100to500')return p.price>=30000&&p.price<=150000;if(r==='500to1000')return p.price>150000&&p.price<=300000;if(r==='1000plus')return p.price>300000;return true;}
function listed(){let items=productList().filter(p=>(!selectedFilter.categories.length||selectedFilter.categories.includes(p.category))&&(!selectedFilter.prices.length||selectedFilter.prices.some(r=>priceMatch(p,r)))&&(!selectedFilter.query||`${p.name} ${p.brand||''} ${p.category}`.toLowerCase().includes(selectedFilter.query.toLowerCase())));switch(selectedFilter.sort){case'low':items.sort((a,b)=>a.price-b.price);break;case'high':items.sort((a,b)=>b.price-a.price);break;case'name':items.sort((a,b)=>a.name.localeCompare(b.name));break;case'rating':items.sort((a,b)=>b.rating-a.rating);break;case'deals':items.sort((a,b)=>(b.oldPrice-b.price)-(a.oldPrice-a.price));break;default:items.sort((a,b)=>a.id-b.id)}return items;}
function renderProducts(){const category=params.get('category');if(categories.includes(category))selectedFilter.categories=[category];const sort=params.get('sort');if(['low','high','rating','deals'].includes(sort))selectedFilter.sort=sort;return shell(`<section class="container listing-layout"><aside class="filters" aria-label="Product filters"><div class="filter-block"><h3>Category</h3>${categories.map(c=>`<label class="check-row"><input type="checkbox" name="category-filter" value="${esc(c)}" ${selectedFilter.categories.includes(c)?'checked':''}><span>${esc(c)}</span></label>`).join('')}</div><div class="filter-block"><h3>Price Range</h3>${[['under100','Under $100'],['100to500','$100 - $500'],['500to1000','$500 - $1000'],['1000plus','$1000+']].map(([k,v])=>`<label class="check-row"><input type="checkbox" name="price-filter" value="${k}"><span>${v}</span></label>`).join('')}</div><button class="btn btn-outline btn-block" data-action="clear-filter">Clear Filters</button></aside><div class="listing-main"><div class="listing-heading"><div><h1>All Products <span id="product-count">(${listed().length})</span></h1><p class="listing-subtitle">Find your next favorite tech</p></div><label class="sort-select">Sort by: <select id="sort-by"><option value="popular">Popularity</option><option value="low">Price: Low to High</option><option value="high">Price: High to Low</option><option value="rating">Top Rated</option><option value="deals">Best Deals</option></select></label></div><div class="mobile-search"><span>${icon('search',18)}</span><input id="mobile-products-search" type="search" placeholder="Search products..." value="${esc(selectedFilter.query)}" aria-label="Search products"></div><div class="mobile-filters-title">${icon('filter',18)} Filter by category and price above</div><div id="products-results" class="products-grid listing-grid">${listed().map(p=>card(p,{meta:true})).join('')}</div></div></section>`);}
function renderProduct(){const p=getProduct(params.get('id')||1);if(!p)return shell(`<div class="container empty-state"><h1>Product not found</h1><a href="products.html" class="btn btn-primary">Browse products</a></div>`);const related=productList().filter(x=>x.category===p.category&&x.id!==p.id).slice(0,4);return shell(`<section class="container detail-wrap"><div class="breadcrumbs"><a href="index.html">Home</a><span>/</span><a href="products.html">Products</a><span>/</span><span>${esc(p.name)}</span></div><div class="product-detail"><div class="detail-image-wrap"><div class="detail-image"><img id="detail-main-image" src="${imagePath(p.image)}" alt="${esc(p.name)} illustration"></div><div class="image-thumbs"><button class="thumb active" aria-label="Main product view"><img src="${imagePath(p.image)}" alt=""></button><button class="thumb" aria-label="Alternate product view"><img src="${imagePath(p.image)}" alt=""></button><button class="thumb" aria-label="Additional product view"><img src="${imagePath(p.image)}" alt=""></button></div></div><div class="detail-info"><div class="eyebrow">${esc(p.category)}</div><h1>${esc(p.name)}</h1><div class="rating">${icon('star',17)} <strong>${p.rating.toFixed(1)}</strong><span>Customer rating</span></div><div class="detail-price">${money(p.price)} <s>${money(p.oldPrice)}</s></div><p class="detail-description">${esc(p.description)}</p><div class="stock-pill">${icon('check',17)} ${p.stock} available in stock</div><div class="detail-controls"><div class="quantity-picker"><button data-action="detail-decrease" aria-label="Decrease quantity">${icon('minus',16)}</button><input id="detail-qty" type="number" min="1" max="${p.stock}" value="1" aria-label="Quantity"><button data-action="detail-increase" aria-label="Increase quantity">${icon('plus',16)}</button></div><button class="btn btn-primary btn-big" data-action="add-detail-cart" data-id="${p.id}">${icon('cart',18)} Add to Cart</button><button class="btn btn-outline btn-icon" data-action="wishlist" data-id="${p.id}" aria-label="Add to wishlist">${icon('heart',20)}</button></div><div class="feature-points"><div>${icon('truck',21)} Fast delivery options</div><div>${icon('shield',21)} Secure checkout demo</div><div>${icon('box',21)} Quality electronics</div></div></div></div></section><section class="container section related-section"><h2>You May Also Like</h2><div class="products-grid four">${related.map(p=>card(p)).join('')}</div></section>`);}
function emptyState(title,desc,link,label,ic='cart'){return `<div class="empty-state"><div class="empty-icon">${icon(ic,35)}</div><h2>${title}</h2><p>${desc}</p><a class="btn btn-primary" href="${link}">${label}</a></div>`;}
function renderCart(){const items=cartRows();const content=items.length?`<div class="cart-layout"><section class="panel cart-items"><div class="table-scroller"><table class="cart-table"><thead><tr><th>Product</th><th>Price</th><th>Quantity</th><th>Total</th><th></th></tr></thead><tbody>${items.map(({qty,product:p})=>`<tr><td><div class="cart-product"><img src="${imagePath(p.image)}" alt=""><div><a href="product.html?id=${p.id}">${esc(p.name)}</a><span>${esc(p.category)}</span></div></div></td><td>${money(p.price)}</td><td><div class="mini-qty"><button data-action="change-qty" data-id="${p.id}" data-delta="-1" aria-label="Decrease quantity">−</button><span>${qty}</span><button data-action="change-qty" data-id="${p.id}" data-delta="1" aria-label="Increase quantity">+</button></div></td><td class="price-emphasis">${money(p.price*qty)}</td><td><button class="plain-icon danger" data-action="remove-cart" data-id="${p.id}" aria-label="Remove ${esc(p.name)}">${icon('trash',19)}</button></td></tr>`).join('')}</tbody></table></div><div class="cart-bottom"><a href="products.html" class="text-link">← Continue Shopping</a><button class="text-link danger" data-action="clear-cart">Clear Cart</button></div></section>${summaryBox(false)}</div>`:emptyState('Your cart is empty','Browse the latest tech and add your favorites to your cart.','products.html','Start Shopping');return shell(`<section class="container interior-page"><h1 class="page-heading">Shopping Cart <span class="muted">(${countCart()} items)</span></h1>${content}</section>`);}
function summaryBox(checkout){const total=subtotal(),ship=total>=100?0:(total>0?15:0);return `<aside class="panel order-summary"><h2>Order Summary</h2><div class="summary-line"><span>Subtotal</span><strong>${money(total)}</strong></div><div class="summary-line"><span>Shipping</span><strong>${ship===0?'Free':money(ship)}</strong></div><div class="summary-line total"><span>Total</span><strong>${money(total+ship)}</strong></div>${checkout?`<div class="secure-note">${icon('shield',18)} This is a demo checkout. No money is charged.</div>`:`<a class="btn btn-primary btn-block btn-big" href="checkout.html">Proceed to Checkout ${icon('arrow',18)}</a>`}</aside>`;}
function renderCheckout(){if(!cartRows().length)return shell(`<section class="container interior-page"><h1 class="page-heading">Secure Checkout</h1>${emptyState('Nothing to check out','Add a product to your cart first.','products.html','Browse Products')}</section>`);const current=user()||{};return shell(`<section class="container interior-page"><h1 class="page-heading">Secure Checkout</h1><div class="checkout-layout"><form id="checkout-form" class="panel checkout-form"><h2>Contact Information</h2><div class="form-row"><label>Full Name<input name="name" value="${esc(current.name||'')}" autocomplete="name" required></label><label>Email Address<input name="email" type="email" value="${esc(current.email||'')}" autocomplete="email" required></label></div><label>Phone Number<input name="phone" type="tel" autocomplete="tel" required></label><h2>Shipping Address</h2><label>Address<input name="address" autocomplete="street-address" required></label><div class="form-row"><label>City<input name="city" autocomplete="address-level2" required></label><label>Postal Code<input name="postal" autocomplete="postal-code" required></label></div><h2>Payment Method</h2><label class="payment-option"><input type="radio" name="payment" value="Cash on Delivery (demo)" checked> Cash on Delivery <span>(demo)</span></label><label class="payment-option"><input type="radio" name="payment" value="Card (demo)"> Card <span>(demo only — no card details collected)</span></label><div class="checkout-actions"><a href="cart.html" class="text-link">← Back to Cart</a><button type="submit" class="btn btn-primary btn-big">Place Demo Order ${icon('arrow',18)}</button></div></form>${summaryBox(true)}</div></section>`);}
function authCard(register=false,admin=false){const title=admin?'Admin Sign In':register?'Create Account':'Welcome Back';const subtitle=admin?'Access the demo store management area':register?'Join ElectroStore and discover your next tech favorite':'Sign in to continue shopping';return `<section class="auth-section"><div class="auth-graphic"><div class="auth-graphic-inner"><div class="auth-mark">${icon(admin?'chart':'bag',37)}</div><h2>Everything you love.<br>One tech store.</h2><p>Find great electronics and manage your shopping experience with ease.</p><img src="assets/img/hero.svg" alt="Electronics illustration"></div></div><div class="auth-card-area"><form id="${admin?'admin-login-form':register?'register-form':'login-form'}" class="auth-card"><a class="brand auth-brand" href="index.html">Electro<span>Store</span></a><h1>${title}</h1><p class="form-subtitle">${subtitle}</p>${register?'<label>Full Name<input type="text" name="name" autocomplete="name" placeholder="Enter your full name" required minlength="2"></label>':''}<label>Email Address<input type="email" name="email" autocomplete="email" placeholder="you@example.com" required></label><label>Password<input type="password" name="password" autocomplete="${register?'new-password':'current-password'}" placeholder="Enter your password" required minlength="6"></label>${register?'<label>Confirm Password<input type="password" name="confirm" autocomplete="new-password" placeholder="Confirm password" required minlength="6"></label>':''}<button type="submit" class="btn btn-primary btn-block btn-big">${admin?'Open Demo Dashboard':register?'Create Demo Account':'Sign In (Demo)'}</button>${admin?'<p class="auth-hint">Demo mode: any email and a 6+ character password open the dashboard. Not real authentication.</p>':register?'<p class="auth-hint">Already have an account? <a href="login.html">Sign In</a></p>':'<p class="auth-hint">New to ElectroStore? <a href="register.html">Create an account</a></p>'}<div class="auth-divider">Demo frontend — no real user authentication</div></form></div></section>`;}
function renderProfile(){const u=user();const myOrders=orders().filter(o=>o.customer?.email===u?.email);return shell(`<section class="container interior-page"><h1 class="page-heading">My Profile</h1><div class="profile-layout"><aside class="panel profile-side"><div class="avatar">${esc((u?.name||'G').slice(0,1).toUpperCase())}</div><h2>${esc(u?.name||'Guest User')}</h2><p>${esc(u?.email||'Sign in for your account details')}</p><div class="profile-links"><a href="#profile-details">${icon('user',18)} Personal Information</a><a href="#my-orders">${icon('orders',18)} My Orders</a><a href="#my-wishlist">${icon('heart',18)} Wishlist</a><button data-action="logout">${icon('logout',18)} Sign Out</button></div></aside><div class="profile-content"><div class="panel info-panel" id="profile-details"><div class="section-heading"><h2>Personal Information</h2><a href="login.html" class="text-link">${u?'Change account':'Sign in'}</a></div><div class="info-grid"><div><span>Full Name</span><strong>${esc(u?.name||'Guest')}</strong></div><div><span>Email Address</span><strong>${esc(u?.email||'Not signed in')}</strong></div></div></div><div class="panel info-panel" id="my-orders"><h2>Order History</h2>${myOrders.length?`<div class="table-scroller"><table class="simple-table"><thead><tr><th>Order</th><th>Date</th><th>Status</th><th>Total</th></tr></thead><tbody>${myOrders.map(o=>`<tr><td>${esc(o.id)}</td><td>${new Date(o.date).toLocaleDateString()}</td><td><span class="status ${o.status.toLowerCase()}">${esc(o.status)}</span></td><td>${money(o.total)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No orders yet. Your demo orders will appear here.</p>'}</div><div class="panel info-panel" id="my-wishlist"><h2>My Wishlist</h2>${wishlist().length?`<div class="wishlist-products">${wishlist().map(id=>getProduct(id)).filter(Boolean).map(p=>`<a href="product.html?id=${p.id}"><img src="${imagePath(p.image)}" alt=""><span>${esc(p.name)}<small>${money(p.price)}</small></span></a>`).join('')}</div>`:'<p class="muted">Your wishlist is empty.</p>'}</div></div></div></section>`);}
function adminShell(content){const links=[['admin.html','chart','Dashboard'],['admin-products.html','box','Products'],['admin-orders.html','orders','Orders'],['admin-deals.html','tag','Deals'],['index.html','bag','View Store']];return `<div class="admin-shell"><aside class="admin-sidebar"><a href="admin.html" class="admin-brand">Electro<span>Store</span><small>ADMIN</small></a><nav aria-label="Admin navigation">${links.map(([url,ic,title])=>`<a class="${location.pathname.endsWith('/'+url)||location.pathname.endsWith(url)?'active':''}" href="${url}">${icon(ic,20)} ${title}</a>`).join('')}</nav><div class="sidebar-bottom"><span>${icon('shield',17)} Store administration</span><a href="admin-login.html">${icon('logout',18)} Sign Out</a></div></aside><div class="admin-main"><header class="admin-topbar"><div><button class="mobile-menu-btn icon-button admin-menu" data-action="toggle-admin-menu" aria-label="Menu">${icon('menu',21)}</button><span>Store Management</span></div><div class="admin-account">${icon('user',18)} Administrator</div></header><main class="admin-content">${content}</main></div></div>`;}
const baseAdminShell = adminShell;
adminShell = content => baseAdminShell(content).replace('<a href="admin-products.html"','<a href="admin-deals.html">'+icon('box',20)+' Deals</a><a href="admin-products.html"');
function statCard(iconName,label,value,desc){return `<div class="panel stat-card"><span class="stat-icon">${icon(iconName,23)}</span><span class="stat-label">${label}</span><strong>${value}</strong><small>${desc}</small></div>`;}
function renderAdmin(){const prods=productList(),os=orders(),revenue=os.reduce((s,o)=>s+o.total,0);const counts=[32,44,40,59,50,70,63,83];return shell(`<div class="admin-heading"><div><h1>Dashboard</h1><p>Here's what's happening with your store.</p></div><span class="date-chip">October 2026</span></div><div class="stats-grid">${statCard('chart','Total Revenue',money(revenue),'From database orders')}${statCard('orders','Total Orders',String(os.length),'Orders in MySQL')}${statCard('box','Total Products',String(prods.length),'Active catalog items')}${statCard('user','Total Customers',String(new Set(os.map(x=>x.customer_email||x.customer?.email)).size),'Customers with orders')}</div><div class="dashboard-panels"><div class="panel chart-panel"><div class="section-heading"><h2>Sales Overview</h2><span class="muted">Placeholder visualization</span></div><div class="bar-chart">${counts.map((n,i)=>`<div class="bar-track"><span style="height:${n}%"></span><small>${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug'][i]}</small></div>`).join('')}</div></div><div class="panel chart-panel"><div class="section-heading"><h2>Recent Orders</h2><a href="admin-orders.html" class="text-link">View all</a></div>${os.length?`<div class="table-scroller"><table class="simple-table"><thead><tr><th>Order</th><th>Total</th><th>Status</th></tr></thead><tbody>${os.slice(-5).reverse().map(o=>`<tr><td>${esc(o.id)}</td><td>${money(o.total)}</td><td><span class="status ${o.status.toLowerCase()}">${esc(o.status)}</span></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No orders yet. Place an order through the storefront to see it here.</p>'}</div></div>`,{admin:true});}
function productTable(){return `<div class="table-scroller"><table class="simple-table admin-table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Actions</th></tr></thead><tbody>${productList().map(p=>`<tr><td><div class="admin-product"><img src="${imagePath(p.image)}" alt=""><span>${esc(p.name)}</span></div></td><td>${esc(p.category)}</td><td>${money(p.price)}</td><td><span class="stock-label ${p.stock<10?'low-stock':''}">${p.stock} in stock</span></td><td class="admin-actions"><button class="small-action" data-action="edit-product" data-id="${p.id}">Edit</button><button class="small-action danger" data-action="delete-product" data-id="${p.id}">Delete</button></td></tr>`).join('')}</tbody></table></div>`;}
function renderAdminProducts(){return shell(`<div class="admin-heading"><div><h1>Manage Products</h1><p>Add, update and organize your product catalog.</p></div><button class="btn btn-primary" data-action="add-product">${icon('plus',18)} Add Product</button></div><section class="panel data-panel" id="admin-product-table">${productTable()}</section><div id="product-modal-container"></div>`,{admin:true});}
function orderDetail(o){return `<div class="order-detail-grid"><section><h3>Customer information</h3><p><strong>${esc(o.customer.name)}</strong><br>${esc(o.customer.email)}<br>User ID: ${esc(o.user_id)}</p></section><section><h3>Shipping information</h3><p><strong>${esc(o.shipping_name)}</strong><br>${esc(o.shipping_email)}<br>${esc(o.shipping_address)}</p></section><section><h3>Payment summary</h3><p>Method: ${esc(o.payment_method)}<br>Status: Unpaid / COD<br>Total: <strong>${money(o.total)}</strong></p></section><section class="order-detail-items"><h3>Ordered products</h3>${o.items.map(i=>`<div class="order-line"><img src="${imagePath(i.image)}" alt=""><span>${esc(i.product_name)}<small>Product #${esc(i.product_id)} · Qty ${esc(i.quantity)} · ${money(i.unit_price)} each</small></span><strong>${money(Number(i.unit_price)*Number(i.quantity))}</strong></div>`).join('')}</section></div>`;}
function orderTable(){const os=orders();return os.length?`<div class="table-scroller"><table class="simple-table admin-table"><thead><tr><th>Order ID</th><th>Customer</th><th>Date</th><th>Items</th><th>Total</th><th>Status</th><th>Action</th></tr></thead><tbody>${os.slice().reverse().map(o=>`<tr><td><strong>${esc(o.id)}</strong></td><td>${esc(o.customer.name)}<small class="table-email">${esc(o.customer.email)}</small></td><td>${new Date(o.date).toLocaleString()}</td><td>${o.items.length}</td><td>${money(o.total)}</td><td><span class="status ${o.status.toLowerCase()}">${esc(o.status)}</span></td><td><button class="small-action" data-action="view-order" data-id="${esc(o.id)}">View Details</button><label class="sr-only" for="status-${esc(o.id)}">Order status</label><select class="status-select" id="status-${esc(o.id)}" data-order="${esc(o.id)}">${['Pending','Processing','Shipped','Delivered','Cancelled'].map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select></td></tr><tr class="order-detail-row" id="order-detail-${esc(o.id)}" hidden><td colspan="7">${orderDetail(o)}</td></tr>`).join('')}</tbody></table></div>`:emptyState('No orders yet','Customer orders will appear here after checkout.','index.html','Go to Store','orders');}
function renderAdminOrders(){return shell(`<div class="admin-heading"><div><h1>Manage Orders</h1><p>Review real customer orders and delivery information.</p></div><span class="date-chip">${orders().length} total orders</span></div><section class="panel data-panel" id="admin-order-table">${orderTable()}</section>`,{admin:true});}
function highlight(text,query){const safe=esc(text),needle=esc(query).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');return needle?safe.replace(new RegExp(`(${needle})`,'ig'),'<mark>$1</mark>'):safe;}
function initSearchAutocomplete(){const input=$('#global-search'),box=$('#search-suggestions');if(!input||!box)return;let timer=0,requestId=0,active=-1;const close=()=>{box.hidden=true;box.innerHTML='';active=-1;};const draw=(items,q)=>{box.innerHTML=items.length?items.map((p,i)=>`<a role="option" class="search-suggestion" href="product.html?id=${p.id}"><img src="${imagePath(p.image)}" alt=""><span><strong>${highlight(p.name,q)}</strong><small>${highlight(p.brand||p.category||'Electronics',q)}</small></span><b>${money(p.deal_id?p.deal_price:p.original_price)}</b></a>`).join('')+`<a class="search-view-all" href="products.html?q=${encodeURIComponent(q)}">View all results</a>`:'<div class="search-no-results">No matching products</div>';box.hidden=false;};input.oninput=()=>{clearTimeout(timer);const q=input.value.trim();if(!q){close();return;}timer=setTimeout(()=>{const id=++requestId;ElectroAPI.get('suggestions',{q}).then(r=>{if(id===requestId)draw(r.data,q);}).catch(()=>{if(id===requestId)close();});},280);};input.onkeydown=e=>{const items=$$('.search-suggestion',box);if(e.key==='Escape'){close();return;}if(e.key==='ArrowDown'){e.preventDefault();active=Math.min(active+1,items.length-1);items.forEach((x,i)=>x.classList.toggle('active',i===active));}if(e.key==='ArrowUp'){e.preventDefault();active=Math.max(active-1,0);items.forEach((x,i)=>x.classList.toggle('active',i===active));}if(e.key==='Enter'&&active>=0&&items[active]){e.preventDefault();location.href=items[active].href;}};document.addEventListener('click',e=>{if(!e.target.closest('#header-search')&&!e.target.closest('#search-suggestions'))close();});}
function dealCard(d){const pct=d.discount_type==='percentage'?Number(d.discount_value):Math.round((1-(Number(d.deal_price)/Number(d.original_price)))*100);return `<article class="product-card deal-card" data-expiry="${esc(d.end_at)}"><a href="product.html?id=${d.product_id}" class="product-art"><img src="${imagePath(d.image)}" alt="${esc(d.name)}" loading="lazy"></a><div class="product-card-body"><span class="deal-badge">${pct}% OFF</span><a class="product-title" href="product.html?id=${d.product_id}">${esc(d.name)}</a><span class="product-category">${esc(d.brand||d.category||'Electronics')}</span><div class="deal-prices"><s>${money(d.original_price)}</s><strong>${money(d.deal_price)}</strong></div><div class="deal-countdown" data-countdown="${esc(d.end_at)}">Loading time…</div><div class="product-card-bottom"><a class="btn btn-outline btn-product" href="product.html?id=${d.product_id}">View Product</a><button class="btn btn-primary btn-product" data-action="add-cart" data-id="${d.product_id}">Add to Cart</button></div></div></article>`;}
function renderDeals(){const deals=productList().filter(p=>p.deal_id);setTimeout(()=>{document.querySelectorAll('[data-countdown]').forEach(el=>{const tick=()=>{const end=new Date(el.dataset.countdown.replace(' ','T')+'+05:30').getTime();const diff=end-Date.now();if(diff<=0){el.closest('.deal-card')?.remove();return;}const s=Math.floor(diff/1000),d=Math.floor(s/86400),h=Math.floor(s%86400/3600),m=Math.floor(s%3600/60),sec=s%60;el.textContent=`${d}d ${String(h).padStart(2,'0')}h ${String(m).padStart(2,'0')}m ${String(sec).padStart(2,'0')}s left`;};tick();setInterval(tick,1000);});},0);return shell(`<section class="container interior-page"><div class="section-heading"><div><h1 class="page-heading">Today’s Deals</h1><p class="listing-subtitle">Limited-time offers from our LKR catalogue.</p></div></div>${deals.length?`<div class="products-grid listing-grid">${deals.map(dealCard).join('')}</div>`:emptyState('No active deals','Check back soon for new offers.','products.html','Browse Products')}</section>`);}
function renderAdminDeals(){const content=`<div class="admin-heading"><div><h1>Manage Deals</h1><p>Create and manage time-limited product discounts.</p></div><button class="btn btn-primary" data-action="add-deal">Add Deal</button></div><section class="panel data-panel" id="admin-deals-table"><div class="boot-message">Loading deals…</div></section><div id="deal-modal-container"></div>`;setTimeout(async()=>{try{const [deals,products]=await Promise.all([ElectroAPI.get('admin_deals'),ElectroAPI.get('admin_products')]);window.ELECTRO_ADMIN_DEALS=deals.data;window.ELECTRO_ADMIN_PRODUCTS=products.data;$('#admin-deals-table').innerHTML=dealTable();}catch(e){$('#admin-deals-table').innerHTML=`<div class="empty-state"><h2>Unable to load deals</h2><p>${esc(e.message)}</p></div>`;}},0);return adminShell(content);}
function dealTable(){return `<div class="table-scroller"><table class="simple-table admin-table"><thead><tr><th>Product</th><th>Discount</th><th>Dates</th><th>Status</th><th>Actions</th></tr></thead><tbody>${(window.ELECTRO_ADMIN_DEALS||[]).map(d=>{const now=Date.now(),st=!d.is_active?'Inactive':new Date(d.start_at.replace(' ','T')+'+05:30')>new Date()?'Scheduled':new Date(d.end_at.replace(' ','T')+'+05:30')<=new Date()?'Expired':'Active';return `<tr><td>${esc(d.name)}</td><td>${d.discount_type==='percentage'?d.discount_value+'%':money(d.discount_value)}</td><td>${esc(d.start_at)} → ${esc(d.end_at)}</td><td><span class="status ${st.toLowerCase()}">${st}</span></td><td><button class="small-action" data-action="edit-deal" data-id="${d.id}">Edit</button><button class="small-action danger" data-action="delete-deal" data-id="${d.id}">Delete</button></td></tr>`;}).join('')}</tbody></table></div>`;}
function dealModal(deal=null){const products=window.ELECTRO_ADMIN_PRODUCTS||[];return `<div class="modal-backdrop"><div class="modal panel"><div class="modal-heading"><h2>${deal?'Edit Deal':'Create Deal'}</h2><button class="plain-icon" data-action="close-deal">×</button></div><form id="deal-form"><input type="hidden" name="id" value="${deal?.id||''}"><label>Product<select name="product_id" required>${products.map(p=>`<option value="${p.id}" ${Number(deal?.product_id)===Number(p.id)?'selected':''}>${esc(p.name)} — ${money(p.price)}</option>`).join('')}</select></label><div class="form-row"><label>Discount Type<select name="discount_type"><option value="percentage" ${deal?.discount_type==='percentage'?'selected':''}>Percentage</option><option value="fixed" ${deal?.discount_type==='fixed'?'selected':''}>Fixed LKR</option></select></label><label>Discount Value<input type="number" name="discount_value" min="0.01" step="0.01" value="${deal?.discount_value||''}" required></label></div><div class="form-row"><label>Starts<input type="datetime-local" name="start_at" value="${deal?.start_at?.replace(' ','T').slice(0,16)||''}" required></label><label>Expires<input type="datetime-local" name="end_at" value="${deal?.end_at?.replace(' ','T').slice(0,16)||''}" required></label></div><div class="modal-actions"><button type="button" class="btn btn-outline" data-action="close-deal">Cancel</button><button class="btn btn-primary">Save Deal</button></div></form></div></div>`;}
function modalProduct(p){const edit=!!p;return `<div class="modal-backdrop" id="product-modal"><div class="modal panel" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-heading"><h2 id="modal-title">${edit?'Edit Product':'Add Product'}</h2><button class="plain-icon" data-action="close-modal" aria-label="Close">${icon('close',20)}</button></div><form id="product-form"><input type="hidden" name="id" value="${edit?p.id:''}"><label>Product Name<input name="name" value="${esc(p?.name||'')}" required maxlength="70"></label><div class="form-row"><label>Category<select name="category" required>${categories.map(c=>`<option ${p?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Price (LKR)<input type="number" name="price" min="0.01" step="0.01" value="${p?.price||''}" required></label></div><div class="form-row"><label>Stock<input type="number" name="stock" min="0" step="1" value="${p?.stock??0}" required></label><label>Illustration<select name="image">${['laptop.svg','phone.svg','headphones.svg','camera.svg','tablet.svg','watch.svg'].map(f=>`<option value="${f}" ${p?.image===f?'selected':''}>${f}</option>`).join('')}</select></label></div><label>Description<textarea name="description" rows="3" maxlength="350">${esc(p?.description||'')}</textarea></label><div class="modal-actions"><button type="button" class="btn btn-outline" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">${edit?'Save Changes':'Add Product'}</button></div></form></div></div>`;}
const routes={home:renderHome,products:renderProducts,product:renderProduct,cart:renderCart,checkout:renderCheckout,login:()=>authCard(),register:()=>authCard(true),'admin-login':()=>authCard(false,true),profile:renderProfile,deals:renderDeals,admin:renderAdmin,'admin-products':renderAdminProducts,'admin-orders':renderAdminOrders,'admin-deals':renderAdminDeals};
async function render(){const app=$('#app');if(!app)return;app.innerHTML='<div class="boot-message">Loading ElectroStore…</div>';try{const products=await ElectroAPI.get('products',{q:params.get('q')||'',category:params.get('category')||''});window.ELECTRO_REMOTE_PRODUCTS=products.data;const me=await ElectroAPI.get('me');if(me.data){window.ELECTRO_REMOTE_USER=me.data;await refreshRemoteCart();if(page==='profile')window.ELECTRO_REMOTE_ORDERS=(await ElectroAPI.get('orders')).data;if(page.startsWith('admin-')||page==='admin'){window.ELECTRO_REMOTE_ADMIN_ORDERS=(await ElectroAPI.get('admin_orders')).data;window.ELECTRO_REMOTE_PRODUCTS=(await ElectroAPI.get('admin_products')).data;}}else{window.ELECTRO_REMOTE_USER=null;window.ELECTRO_REMOTE_CART=[];}app.innerHTML=(routes[page]||renderHome)();$$('.check-row span').forEach(label=>{label.textContent=label.textContent.replace('Under $100','Under Rs. 30,000').replace('$100 - $500','Rs. 30,000 - Rs. 150,000').replace('$500 - $1000','Rs. 150,000 - Rs. 300,000').replace('$1000+','Rs. 300,000+');});const sort=$('#sort-by');if(sort)sort.value=selectedFilter.sort;}catch(e){app.innerHTML=`<section class="container empty-state"><h1>Unable to load the store</h1><p>${esc(e.message)}</p><button class="btn btn-primary" onclick="location.reload()">Try Again</button></section>`;}}
function renderFiltered(){const e=$('#products-results');if(!e)return;const found=listed();e.innerHTML=found.length?found.map(p=>card(p,{meta:true})).join(''):'<div class="no-results"><h3>No products found</h3><p>Try changing your search or filters.</p></div>';$('#product-count').textContent=`(${found.length})`;}
async function setQty(id,delta){const row=cart().find(i=>i.id===id),next=(row?.qty||0)+delta;if(next<0)return;try{await ElectroAPI.post(next===0?'cart_remove':'cart_update',{product_id:id,quantity:next});await refreshRemoteCart();await render();}catch(e){toast(e.message,'err');}}
async function checkout(form){const data=new FormData(form),valid=['name','email','phone','address','city','postal'].every(k=>clean(data.get(k)));if(!valid){toast('Please complete your shipping details','err');return;}const button=form.querySelector('button[type="submit"]');if(button)button.disabled=true;try{const result=await ElectroAPI.post('checkout',{name:clean(data.get('name')),email:clean(data.get('email')),phone:clean(data.get('phone')),address:clean(data.get('address')),city:clean(data.get('city')),postal:clean(data.get('postal'))});await refreshRemoteCart();$('#main').innerHTML=`<section class="container interior-page">${emptyState('Order placed!','Order #'+esc(result.data.order_id)+' was created with Cash on Delivery.','profile.html#my-orders','View My Orders','check')}</section>`;toast('Order placed successfully');window.scrollTo(0,0);}catch(e){if(button)button.disabled=false;toast(e.message,'err');}}
async function loginSubmit(form,isRegister=false,isAdmin=false){const data=new FormData(form),email=clean(data.get('email')).toLowerCase(),pw=String(data.get('password')||'');if(!email.includes('@')||pw.length<6){toast('Enter a valid email and a 6+ character password','err');return;}if(isRegister&&pw!==String(data.get('confirm')||'')){toast('Passwords do not match','err');return;}try{const result=await ElectroAPI.post(isRegister?'register':'login',{name:clean(data.get('name')),email,password:pw});if(isAdmin&&result.data.role!=='admin')throw new Error('Administrator access required');window.ELECTRO_REMOTE_USER=result.data;location.href=isAdmin?'admin.html':'profile.html';}catch(e){toast(e.message,'err');}}
async function submitProduct(form){const fd=new FormData(form);const id=Number(fd.get('id'));const values={id,name:clean(fd.get('name')),category:clean(fd.get('category')),price:Number(fd.get('price')),stock:Number(fd.get('stock')),image:clean(fd.get('image')),description:clean(fd.get('description'))};if(!values.name||values.price<=0||values.stock<0){toast('Please enter valid product details','err');return;}try{await ElectroAPI.post('admin_products',values);window.ELECTRO_REMOTE_PRODUCTS=(await ElectroAPI.get('admin_products')).data;$('#product-modal-container').innerHTML='';$('#admin-product-table').innerHTML=productTable();toast('Product saved');}catch(e){toast(e.message,'err');}}
document.addEventListener('click',e=>{const thumb=e.target.closest('.image-thumbs .thumb');if(thumb){$$('.image-thumbs .thumb').forEach(x=>x.classList.remove('active'));thumb.classList.add('active');const main=$('#detail-main-image');if(main)main.style.transform=`rotate(${[0,-5,5][$$('.image-thumbs .thumb').indexOf(thumb)]}deg)`;return;}const trigger=e.target.closest('[data-action]');if(!trigger)return;const action=trigger.dataset.action,id=Number(trigger.dataset.id);switch(action){
  case'toggle-menu':$('.site-header')?.classList.toggle('menu-open');break;
  case'toggle-admin-menu':$('.admin-sidebar')?.classList.toggle('show');break;
  case'view-order':{const row=$(`#order-detail-${id}`);if(row)row.hidden=!row.hidden;break;}
  case'confirm-order':if(confirm('Confirm this pending order?'))ElectroAPI.post('admin_orders',{id,status:'Confirmed'}).then(()=>{toast('Order confirmed');render();}).catch(e=>toast(e.message,'err'));break;
  case'add-cart':addCart(id);break;
  case'add-detail-cart':addCart(id,Math.max(1,Number($('#detail-qty')?.value)||1));break;
  case'detail-decrease':{const q=$('#detail-qty');if(q)q.value=Math.max(1,Number(q.value)-1);break;}
  case'detail-increase':{const q=$('#detail-qty');if(q)q.value=Math.min(Number(q.max),Number(q.value)+1);break;}
  case'wishlist':{let arr=wishlist();arr=arr.includes(id)?arr.filter(x=>x!==id):[...arr,id];storage.write('wishlist',arr);toast(arr.includes(id)?'Added to wishlist':'Removed from wishlist');break;}
  case'change-qty':setQty(id,Number(trigger.dataset.delta));break;
  case'remove-cart':saveCart(cart().filter(x=>x.id!==id));render();toast('Removed from cart');break;
  case'clear-cart':saveCart([]);render();toast('Cart cleared');break;
  case'clear-filter':selectedFilter={categories:[],prices:[],sort:'popular',query:''};$$('input[type=checkbox]',$('.filters')).forEach(x=>x.checked=false);const sort=$('#sort-by');if(sort)sort.value='popular';const search=$('#mobile-products-search');if(search)search.value='';renderFiltered();break;
  case'logout':ElectroAPI.post('logout',{}).finally(()=>{window.ELECTRO_REMOTE_USER=null;toast('Signed out');setTimeout(()=>location.href='login.html',500);});break;
  case'add-product':$('#product-modal-container').innerHTML=modalProduct(null);break;
  case'edit-product':$('#product-modal-container').innerHTML=modalProduct(getProduct(id));break;
  case'close-modal':$('#product-modal-container').innerHTML='';break;
  case'add-deal':$('#deal-modal-container').innerHTML=dealModal();break;
  case'edit-deal':$('#deal-modal-container').innerHTML=dealModal((window.ELECTRO_ADMIN_DEALS||[]).find(d=>Number(d.id)===id));break;
  case'close-deal':$('#deal-modal-container').innerHTML='';break;
  case'delete-deal':if(confirm('Delete this deal?'))ElectroAPI.post('admin_deal_delete',{id}).then(()=>render()).catch(e=>toast(e.message,'err'));break;
  case'delete-product':{const p=getProduct(id);if(!p)return;if(!confirm('Delete '+p.name+' from the demo catalog?'))return;ElectroAPI.post('admin_product_delete',{id}).then(()=>render()).catch(e=>toast(e.message,'err'));break;}
}});
document.addEventListener('input',e=>{if(e.target.id==='mobile-products-search'){selectedFilter.query=e.target.value.trim();renderFiltered();}});
document.addEventListener('change',e=>{const x=e.target;if(x.matches('[name="category-filter"]')){selectedFilter.categories=$$('[name="category-filter"]:checked').map(v=>v.value);renderFiltered();}if(x.matches('[name="price-filter"]')){selectedFilter.prices=$$('[name="price-filter"]:checked').map(v=>v.value);renderFiltered();}if(x.id==='sort-by'){selectedFilter.sort=x.value;renderFiltered();}if(x.matches('.status-select')){ElectroAPI.post('admin_orders',{id:x.dataset.order,status:x.value}).then(()=>{toast('Order status updated');render();}).catch(err=>toast(err.message,'err'));}});
document.addEventListener('submit',e=>{const form=e.target,formId=form.getAttribute('id');if(['login-form','register-form','admin-login-form','checkout-form','product-form'].includes(formId)){e.preventDefault();if(formId==='checkout-form')checkout(form);if(formId==='login-form')loginSubmit(form);if(formId==='register-form')loginSubmit(form,true);if(formId==='admin-login-form')loginSubmit(form,false,true);if(formId==='product-form')submitProduct(form);}});
document.addEventListener('submit',e=>{if(e.target.id!=='deal-form')return;e.preventDefault();const fd=new FormData(e.target);ElectroAPI.post('admin_deals',Object.fromEntries(fd.entries())).then(()=>{toast('Deal saved');render();}).catch(err=>toast(err.message,'err'));});
let orderPollTimer=0,orderPollBusy=false,orderPollSnapshot={};
function orderStatusCopy(status){return {Pending:'Order Placed — Awaiting confirmation.',Confirmed:'Order Confirmed — Your order has been approved.',Processing:'Processing — We are preparing your order.',Shipped:'Shipped — Your order is on its way.',Delivered:'Delivered — Your order has been delivered.',Cancelled:'Order Cancelled.'}[status]||status;}
function trackingMarkup(o){const stages=['Pending','Confirmed','Processing','Shipped','Delivered'];const current=stages.indexOf(o.status);return `<article class="customer-order-tracking"><div><strong>Order #${esc(o.id)}</strong><span class="status ${o.status.toLowerCase()}">${esc(o.status)}</span></div><p>${esc(orderStatusCopy(o.status))}</p>${o.status==='Cancelled'?'':`<div class="tracking-steps">${stages.map((s,i)=>`<span class="${i<=current?'complete':''}">${esc(s==='Pending'?'Order Placed':s)}</span>`).join('')}</div>`}</article>`;}
function drawCustomerTracking(rows){const host=$('#my-orders');if(!host)return;let panel=$('#customer-order-tracking');if(!panel){panel=document.createElement('div');panel.id='customer-order-tracking';panel.className='panel info-panel';panel.innerHTML='<h2>Order Tracking</h2><div class="tracking-list"></div>';host.appendChild(panel);}panel.querySelector('.tracking-list').innerHTML=rows.map(trackingMarkup).join('');}
async function pollCustomerOrders(showNotice=false){if(orderPollBusy||document.hidden||page!=='profile')return;orderPollBusy=true;try{const result=await ElectroAPI.get('orders'),rows=result.data.map(normalizeOrder);rows.forEach(o=>{if(showNotice&&orderPollSnapshot[o.id]&&orderPollSnapshot[o.id]!==o.status&&o.status!=='Pending')toast(orderStatusCopy(o.status),'success');orderPollSnapshot[o.id]=o.status;});drawCustomerTracking(rows);}catch(e){if(e.status===401)window.location.href='login.html';}finally{orderPollBusy=false;}}
function initCustomerOrderPolling(){if(page!=='profile')return;clearInterval(orderPollTimer);pollCustomerOrders(false);orderPollTimer=setInterval(()=>pollCustomerOrders(true),12000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)pollCustomerOrders(true);},{once:false});}
function ensureAdminOrderControls(){if(!page.includes('admin'))return;document.querySelectorAll('.status-select').forEach(select=>{if(![...select.options].some(o=>o.value==='Confirmed'))select.insertAdjacentHTML('afterbegin','<option>Confirmed</option>');if(select.value==='Pending'&&!select.parentElement.querySelector('[data-action="confirm-order"]'))select.insertAdjacentHTML('afterbegin',`<button class="small-action" data-action="confirm-order" data-id="${select.dataset.order}">Confirm Order</button>`);});}
const appRender = render;
render = async () => { await appRender(); const sort=$('#sort-by'); if(sort&&!sort.querySelector('[value="name"]')) sort.insertAdjacentHTML('beforeend','<option value="name">Name: A to Z</option>'); initSearchAutocomplete(); initCustomerOrderPolling(); ensureAdminOrderControls(); };
render();
})();
